void PageHandlerAsyncWaiter::ReadPref(
    const std::string& pref_name, ::base::Value* out_s) {
  base::RunLoop loop;
  proxy_->ReadPref(std::move(pref_name),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::base::Value* out_s
,
             ::base::Value s) {*out_s = std::move(s);
            loop->Quit();
          },
          &loop,
          out_s));
  loop.Run();
}

